function requirementMatches(r){const query=els.search.value.trim().toLowerCase();const hay=[r.id,r.title,r.intent,...(r.components||[]).flatMap(c=>[c.id,c.name,...(c.responsibilities||[])])].join(' ').toLowerCase();if(query&&!hay.includes(query))return false;if(state.filter==='changed'&&!r.changed)return false;if(state.filter==='drift'&&r.convergence!=='needs_convergence')return false;if(state.filter==='incomplete'&&r.convergence!=='incomplete')return false;return true}
