function implementationRows(items){if(!items.length)return `<div class="empty">${esc(t('No implementation reference declared.'))}</div>`;return `<div class="impl-list">${items.map(item=>`<div class="impl ${item.changed?'changed':''} ${item.resolved?'':'unresolved'}"><div class="impl-path">${esc(item.target)}</div><div class="impl-meta">${esc(statusLabel(item.resolved?'resolved':'unresolved'))} · ${esc(item.provider)} / ${esc(statusLabel(item.precision))}${item.changed?` · ${esc(localized('changed now','当前已变更'))}`:''}</div></div>`).join('')}</div>`}
function designComponents(r){return r.components.map(component=>`<div class="component-card ${component.changed?'changed':''}"><div class="req-top"><div><b>${esc(component.name)}</b><div class="component-id">${esc(component.id)}</div></div>${pill(unit(component.implementation_lines,'line','lines','行'))}</div>${component.responsibilities.length?`<ul class="responsibilities">${component.responsibilities.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:`<div class="empty">${esc(t('No responsibilities declared.'))}</div>`}${component.depends_on.length?`<div class="pills">${component.depends_on.map(dependency=>pill(localized(`depends on ${dependency}`,`依赖 ${dependency}`))).join('')}</div>`:''}</div>`).join('')||`<div class="empty">${esc(t('No implementation component declared.'))}</div>`}
function acceptanceNodes(r){return r.acceptance.map(a=>`<div class="accept-card"><b>${esc(a.title)}</b><div class="component-id">${esc(a.id)}</div><small>${esc(a.statement)}</small></div>`).join('')||`<div class="empty">${esc(t('No acceptance criterion declared.'))}</div>`}
function actualComponents(r){return r.components.map(component=>`<div class="component-card ${component.changed?'changed':''}"><div class="req-top"><div><b>${esc(component.name)}</b><div class="component-id">${esc(component.id)}</div></div><div class="pills">${pill(unit(component.implementation_lines,'line','lines','行'))}${component.changed?pill(statusLabel('changed'),'warn'):pill(statusLabel('current'),'good')}</div></div>${implementationRows(component.implementation)}</div>`).join('')||`<div class="empty">${esc(t('No current implementation mapping.'))}</div>`}
function dependencyRows(r){const deps=r.dependency_alignment||[];if(!deps.length)return `<div class="empty">${esc(t('No cross-component dependency is declared or detected for this feature.'))}</div>`;return `<div class="deps">${deps.map(dep=>{const tone=dep.blocking?'warn':dep.status==='aligned'?'good':'info',precision=dep.precision==='not_observed'?t('not observed'):statusLabel(dep.precision);return `<div class="dep"><div><b>${esc(dep.from_name)}</b><div class="component-id">${esc(dep.from)}</div></div><div class="arrow">→</div><div><b>${esc(dep.to_name)}</b><div class="component-id">${esc(dep.to)}</div></div><div class="dep-state">${pill(statusLabel(dep.status),tone)}<div class="panel-meta">${esc(precision)} · ${dep.blocking?t('blocker'):dep.status==='aligned'?t('evidence'):t('advisory')}</div></div></div>`}).join('')}</div>`}
function verificationBlock(r){if(!r.acceptance.length)return `<div class="empty">${esc(t('No acceptance criteria.'))}</div>`;return `<div class="verification">${r.acceptance.map(a=>`<div class="verification-item"><div class="req-top"><b>${esc(a.title)}</b><code>${esc(a.id)}</code></div><div class="statement">${esc(a.statement)}</div>${implementationRows(a.verification)}</div>`).join('')}</div>`}
function featureFlow(r){const impl=(r.components||[]).flatMap(c=>c.implementation||[]),resolved=impl.filter(i=>i.resolved).length,ver=(r.acceptance||[]).flatMap(a=>a.verification||[]),verified=ver.filter(i=>i.resolved).length,blockers=r.convergence_blockers||[];const steps=[[t('Desired State'),statusLabel(r.status==='complete'?'declared':'incomplete'),localized(`${r.components.length} components · ${r.acceptance.length} acceptance criteria`,`${r.components.length} 个组件 · ${r.acceptance.length} 个验收条件`),r.status==='complete'?'good':'warn'],[t('Actual State'),localized(`${resolved}/${impl.length} references resolved`,`${resolved}/${impl.length} 个引用已解析`),localized(`${num(r.implementation_lines)} lines · ${r.implementation_symbols} symbols`,`${num(r.implementation_lines)} 行 · ${r.implementation_symbols} 个符号`),resolved===impl.length?'good':'warn'],[t('Change'),r.changed?localized('changing','变更中'):localized('no mapped change','无映射变更'),r.changed?`+${r.change_additions}/-${r.change_deletions}`:localized('working tree stable','工作树稳定'),r.changed?'warn':'good'],[t('Proof'),localized(`${verified}/${ver.length} verification references`,`${verified}/${ver.length} 个验证引用`),ver.length&&verified===ver.length?localized('acceptance mapped','验收已映射'):localized('verification mapping incomplete','验证映射不完整'),ver.length&&verified===ver.length?'good':'warn'],[t('Convergence'),statusLabel(r.convergence),blockers.length?`${blockers.length} ${blockers.length===1?t('blocker'):t('blockers')}`:localized('design and actual state aligned','设计与实际状态已对齐'),statusClass(r.convergence)]];return `<div class="convergence-flow">${steps.map(([label,value,detail,tone])=>`<div class="flow-step"><div class="flow-label">${esc(label)}</div><div class="flow-value ${tone}">${esc(value)}</div><div class="flow-detail">${esc(detail)}</div></div>`).join('')}</div>`}
function requirementChanges(r){return (state.project.changes||[]).filter(change=>(change.affected_requirements||[]).includes(r.id))}
function renderDetail(){const r=(state.project?.requirements||[]).find(item=>item.id===state.selected);if(!r){setHtml('detail',els.detail,`<div class="section empty">${esc(t('Select a requirement.'))}</div>`);return}const deps=r.dependency_alignment||[],blockingDeps=deps.filter(dep=>dep.blocking),advisories=deps.filter(dep=>!dep.blocking&&dep.status!=='aligned'),changes=requirementChanges(r);const alignmentSignals=[];if(blockingDeps.length)alignmentSignals.push(pill(localized(`${blockingDeps.length} dependency ${blockingDeps.length===1?t('blocker'):t('blockers')}`,`${blockingDeps.length} 个依赖${blockingDeps.length===1?t('blocker'):t('blockers')}`),'warn'));if(advisories.length)alignmentSignals.push(pill(localized(`${advisories.length} dependency ${t('advisory')}`,`${advisories.length} 个依赖${t('advisory')}`),'info'));if(!alignmentSignals.length)alignmentSignals.push(pill(localized('dependencies aligned','依赖已对齐'),'good'));const html=`<div class="feature-head"><div class="eyebrow"><span>${esc(r.id)}</span><span>·</span><span>${esc(statusLabel(r.priority))}</span><span>·</span><span>${esc(statusLabel(r.status))}</span></div><h2>${esc(r.title)}</h2><div class="intent">${esc(r.intent)}</div><div class="pills">${pill(statusLabel(r.convergence),statusClass(r.convergence))}${r.changed?pill(localized(`changed +${r.change_additions}/-${r.change_deletions}`,`已变更 +${r.change_additions}/-${r.change_deletions}`),'warn'):pill(localized('no mapped implementation change','无映射实现变更'),'good')}${pill(unit(r.implementation_files,'file','files','个文件'))}${pill(unit(r.implementation_symbols,'symbol','symbols','个符号'))}${pill(unit(r.implementation_lines,'line','lines','行'))}${pill(unit(r.acceptance.length,'acceptance criterion','acceptance criteria','个验收条件'))}</div></div>${featureFlow(r)}<section class="section"><h3>${esc(t('Feature architecture · desired vs actual'))}</h3><div class="alignment-banner"><div><strong class="${statusClass(r.convergence)}">${esc(statusLabel(r.convergence))}</strong><div class="panel-meta">${esc(t('positive evidence note'))}${r.convergence_blockers?.length?` ${esc(r.convergence_blockers.slice(0,3).join(' · '))}`:''}</div></div><div class="pills">${alignmentSignals.join('')}</div></div><div class="architecture-lane"><div class="lane-label">${esc(t('Design architecture'))}</div><div class="arch-flow"><div class="node"><b>${esc(r.title)}</b><small>${esc(r.id)} · ${esc(t('requirement'))}</small></div><div class="connector">→</div><div class="node-stack">${designComponents(r)}</div><div class="connector">→</div><div class="node-stack">${acceptanceNodes(r)}</div></div></div><div class="architecture-lane"><div class="lane-label">${esc(t('Actual code architecture · generated from current implementation'))}</div><div class="actual-grid">${actualComponents(r)}</div><div class="lane-spacer"></div>${dependencyRows(r)}</div></section><section class="section"><div class="two"><div><h3>${esc(t('Acceptance & verification'))}</h3>${verificationBlock(r)}</div><div><h3>${esc(t('Constraints, decisions & drift'))}</h3>${r.constraints.length?r.constraints.map(c=>`<div class="info-card"><h4>${esc(c.title)}</h4><div class="component-id">${esc(c.id)}</div><div class="panel-meta card-copy">${esc(c.statement)}</div></div>`).join(''):`<div class="empty">${esc(t('No requirement-specific constraints.'))}</div>`}${r.decisions?.length?`<div class="card-gap"></div>${r.decisions.map(d=>`<div class="info-card"><div class="req-top"><h4>${esc(d.title)}</h4>${pill(statusLabel(d.status),'accent')}</div><div class="component-id">${esc(d.id)}</div><div class="card-copy">${esc(d.decision)}</div>${d.rationale?`<div class="panel-meta card-copy">${esc(d.rationale)}</div>`:''}</div>`).join('')}`:''}${r.drift.length?`<div class="card-gap"></div><div class="risk-list">${r.drift.map(item=>`<div class="risk drift">${esc(item)}</div>`).join('')}</div>`:''}</div></div></section><section class="section"><h3>${esc(t('Current changes touching this feature'))}</h3>${changes.length?changeTable(changes,true):`<div class="empty">${esc(t('No current working-tree file is mapped to this requirement.'))}</div>`}</section>`;setHtml('detail',els.detail,html)}

function changeTable(items,compact=false){return `<table class="table"><thead><tr><th>${esc(t('Path'))}</th><th>${esc(t('Status'))}</th><th>${esc(t('Scope'))}</th><th>${esc(t('Diff'))}</th>${compact?'':`<th>${esc(t('Requirements'))}</th>`}</tr></thead><tbody>${items.slice(0,120).map(item=>`<tr><td><div class="change-path"><code>${esc(item.path)}</code></div></td><td>${esc(statusLabel(item.status))}${item.untracked?` · ${esc(t('untracked'))}`:''}</td><td>${esc(item.scope||'—')}</td><td>${changeNums(item)}</td>${compact?'':`<td>${(item.affected_requirements||[]).slice(0,6).map(id=>`<a class="click-req" data-req="${esc(id)}">${esc(id)}</a>`).join(' · ')||'—'}</td>`}</tr>`).join('')}</tbody></table>`}
function renderChanges(){const items=state.project.changes||[],html=items.length?changeTable(items,false):`<div class="section empty">${esc(t('Working tree is clean or Git review is unavailable.'))}</div>`;setHtml('changes',els.changes,html,()=>els.changes.querySelectorAll('[data-req]').forEach(link=>link.addEventListener('click',()=>{state.selected=link.dataset.req;invalidate('requirements','detail');renderRequirements();renderDetail();els.detail.scrollIntoView({behavior:'smooth',block:'start'})})))}
function bars(items){if(!items?.length)return `<div class="empty">${esc(t('No data.'))}</div>`;const max=Math.max(...items.map(item=>Number(item.lines||0)),1);return `<div class="bars">${items.map(item=>`<div class="bar-row"><div class="bar-name">${esc(item.name)}</div><div class="bar-track"><progress class="bar-progress" max="100" value="${Math.max(2,Math.round((item.lines/max)*100))}"></progress></div><div class="bar-val">${esc(unit(item.files,'file','files','个文件'))} · ${esc(unit(item.lines,'line','lines','行'))}</div></div>`).join('')}</div>`}
function renderCodeStats(){const c=state.project.code||{},html=`<div class="two"><div><h3>${esc(t('Languages'))}</h3>${bars(c.languages||[])}</div><div><h3>${esc(t('Product Scopes'))}</h3>${bars(c.product_scopes||[])}</div></div>${c.graph_truncated?`<div class="alignment-banner compact-banner"><strong class="warn">${esc(t('Bounded snapshot'))}</strong><span class="panel-meta">${esc(t('bounded graph note'))}</span></div>`:''}`;setHtml('codeStats',els.codeStats,html)}
function renderRevisions(){const p=state.project,d=p.latest_delta,h=p.history||[],risks=p.risk?.risks||[];const html=`${d?`<div class="delta"><b>${esc(t('Latest structural delta'))}</b><div class="panel-meta">${time(d.from_captured_at_ms)} → ${time(d.to_captured_at_ms)}</div><div class="pills">${pill(`${t('nodes')} +${d.added_nodes}/-${d.removed_nodes}/~${d.changed_nodes}`,'accent')}${pill(`${t('edges')} +${d.added_edges}/-${d.removed_edges}/~${d.changed_edges}`,'accent')}</div>${d.changed_paths?.length?`<div class="impl-list">${d.changed_paths.slice(0,12).map(path=>`<div class="impl"><div class="impl-path">${esc(path)}</div></div>`).join('')}</div>`:''}</div>`:`<div class="empty">${esc(t('No previous meaningful graph revision yet.'))}</div>`}<div class="revision-list">${h.slice(0,10).map(entry=>`<div class="revision"><div class="revision-mark"></div><div><div class="revision-id">${esc(entry.id)}</div><div class="revision-meta">${time(entry.captured_at_ms)} · ${esc(unit(entry.files_indexed,'file','files','个文件'))}${entry.truncated?` · ${esc(t('truncated'))}`:''}</div></div><div class="revision-meta">${num(entry.nodes)} ${esc(t('nodes'))} / ${num(entry.edges)} ${esc(t('edges'))}</div></div>`).join('')}</div>${risks.length?`<h3 class="risk-heading">${esc(t('Current structured risks'))}</h3><div class="risk-list">${risks.slice(0,8).map(risk=>`<div class="risk ${esc(risk.level)}"><b>${esc(statusLabel(risk.category))} · ${esc(statusLabel(risk.level))}</b><div>${esc(risk.summary)}</div></div>`).join('')}</div>`:''}`;setHtml('revisions',els.revisions,html)}
function qualityProviders(language,capability){return (language.providers||[]).filter(provider=>provider.capability===capability&&provider.declared&&provider.available)}
function qualityCell(language,capability){const providers=qualityProviders(language,capability);return providers.length?`<span title="${esc(providers.map(provider=>provider.id).join(', '))}">${pill(t('covered'),'good')}</span>`:`<span class="panel-meta">${esc(t('gap'))}</span>`}
function renderLanguageQuality(){const q=state.project.language_quality||{},languages=(q.languages||[]).filter(language=>Number(language.detected_files||0)>0),dimensions=q.dimensions||[],gaps=languages.reduce((sum,language)=>sum+(language.gaps||[]).length,0);els.qualitySummary.textContent=localized(`${languages.length} languages · ${gaps} ${t(gaps===1?'gap':'gaps')}`,`${languages.length} 种语言 · ${gaps} 个缺口`);if(!languages.length){setHtml('languageQuality',els.languageQuality,`<div class="section empty">${esc(t('No supported source language detected in the bounded repository snapshot.'))}</div>`);return}const summary=dimensions.slice(0,8).map(dimension=>pill(`${dimensionLabel(dimension.dimension)} ${dimension.covered_languages}/${dimension.detected_languages}`,dimension.covered_languages===dimension.detected_languages?'good':'info')).join('');const html=`<div class="section quality-summary"><div class="pills">${summary}</div></div><table class="table"><thead><tr><th>${esc(t('Language'))}</th><th>${esc(t('Files'))}</th><th>${esc(t('Syntax'))}</th><th>${esc(t('Semantic'))}</th><th>${esc(t('Format'))}</th><th>${esc(t('Lint'))}</th><th>${esc(t('Type'))}</th><th>${esc(t('Static'))}</th><th>${esc(t('Test'))}</th><th>${esc(t('Security'))}</th><th>${esc(t('Advanced'))}</th><th>${esc(t('Gaps'))}</th></tr></thead><tbody>${languages.map(language=>`<tr><td><code>${esc(language.language)}</code></td><td>${num(language.detected_files)}</td><td>${pill('tree-sitter','good')}</td><td>${language.semantic_available?`<span title="${esc(language.semantic_provider||localized('semantic provider','语义分析器'))}">${pill(statusLabel(language.semantic_runnable?'ready':'available'),language.semantic_runnable?'good':'info')}</span>`:`<span class="panel-meta">${esc(t('Syntax fallback'))}</span>`}</td><td>${qualityCell(language,'format')}</td><td>${qualityCell(language,'lint')}</td><td>${qualityCell(language,'type_check')}</td><td>${qualityCell(language,'static_analysis')}</td><td>${qualityCell(language,'test')}</td><td>${qualityCell(language,'security')}</td><td>${(language.advanced_stages||[]).length?(language.advanced_stages||[]).map(stage=>pill(dimensionLabel(stage),'accent')).join(' '):'<span class="panel-meta">—</span>'}</td><td>${(language.gaps||[]).length?`<span class="info" title="${esc(language.gaps.join(' · '))}">${language.gaps.length} ${esc(t(language.gaps.length===1?'gap':'gaps'))}</span>`:`<span class="good">${esc(t('declared coverage complete'))}</span>`}</td></tr>`).join('')}</tbody></table>`;setHtml('languageQuality',els.languageQuality,html)}

function renderWorkspaceOptions(){const options=(state.project?.workspace_options||[]).map(workspace=>`<option value="${esc(workspace.id)}" ${workspace.id===state.current?'selected':''}>${esc(workspace.id)} — ${esc(workspace.root||'')}</option>`).join('');setHtml('workspaceOptions',els.workspace,options)}
function renderProject(force=false){if(!state.project)return;if(force)state.rendered.clear();renderWorkspaceOptions();renderLive();renderStats();renderAttention();renderArchitecture();renderRequirements();renderDetail();renderChanges();renderCodeStats();renderRevisions();renderLanguageQuality()}

const revisionKey=revision=>`${revision.fingerprint||'full'}|${revision.graph_revision||''}`;
async function primeRevision(){try{const revision=await uiJson('/intelligence/revision');state.revisionKey=revisionKey(revision);return true}catch{return false}}
async function refreshProject({workspace,reason='auto',force=false}={}){if(workspace!==undefined&&workspace!==state.current){state.current=workspace;state.selected='';state.selectedComponent='';state.revisionKey=null;force=true}if(state.inFlight){if(reason==='auto')return;if(state.controller)state.controller.abort()}if(reason!=='auto'&&state.revisionKey===null)await primeRevision();const controller=new AbortController();state.controller=controller;const epoch=++state.requestEpoch;state.inFlight=true;setSync('loading',reason==='auto'?t('Syncing'):t('Refreshing project state…'));try{const response=await fetch('/intelligence/project',{headers:requestHeaders(),signal:controller.signal});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();if(epoch!==state.requestEpoch)return;state.project=data;state.current=data.workspace;state.lastUpdated=Date.now();if(state.selected&&!data.requirements?.some(r=>r.id===state.selected))state.selected='';renderProject(force);setSync('ok',t('Live'))}catch(error){if(error.name!=='AbortError'){setSync('error',`${t('Refresh failed')} · ${error.message}`)}}finally{if(state.controller===controller){state.inFlight=false;state.controller=null}}}
async function pollRevision(){try{const revision=await uiJson('/intelligence/revision');if(state.project&&Number(state.project.pending_authorizations||0)!==Number(revision.pending_authorizations||0)){state.project.pending_authorizations=Number(revision.pending_authorizations||0);renderAttention()}const key=revisionKey(revision);if(state.revisionKey===null){state.revisionKey=key;await refreshProject({reason:'auto'});return}if(revision.full_refresh_required||key!==state.revisionKey){state.revisionKey=key;await refreshProject({reason:'auto'});if(state.project){const latestGraph=state.project.history?.[0]?.id||revision.graph_revision||'';state.revisionKey=`${revision.fingerprint||'full'}|${latestGraph}`}}else{setSync('ok',t('Live'))}}catch(error){await refreshProject({reason:'auto'})}}
async function refreshSemantics(){els.refreshSemantic.disabled=true;setSync('loading',t('Syncing'));try{await uiJson('/intelligence/semantic-refresh','POST',{});state.semanticRefreshPending=false;setSync('ok',t('Semantic refresh complete'));state.revisionKey=null;await refreshProject({reason:'manual',force:true})}catch(error){if(error.message.includes('authorization required')){state.semanticRefreshPending=true;els.accessPanel.classList.remove('hidden');await loadAccess();setSync('warn',t('Semantic refresh needs approval'))}else{state.semanticRefreshPending=false;setSync('error',`${t('Refresh failed')} · ${error.message}`)}}finally{els.refreshSemantic.disabled=false}}
async function refreshTick(){state.timer=null;if(!els.auto.checked||document.hidden)return;await pollRevision();if(els.auto.checked&&!document.hidden)state.timer=setTimeout(refreshTick,8000)}
function schedule(){clearTimeout(state.timer);state.timer=null;if(els.auto.checked&&!document.hidden)state.timer=setTimeout(refreshTick,8000)}

els.workspace.addEventListener('change',async()=>{await refreshProject({workspace:els.workspace.value,reason:'manual',force:true});if(!els.accessPanel.classList.contains('hidden'))await loadAccess()});
els.language.addEventListener('change',()=>{state.language=els.language.value==='zh-CN'?'zh-CN':'en';localStorage.setItem('wcode.ui.language',state.language);applyLanguage()});
els.theme.addEventListener('change',()=>{state.theme=['dark','light'].includes(els.theme.value)?els.theme.value:'system';localStorage.setItem('wcode.ui.theme',state.theme);applyTheme()});
els.manage.addEventListener('click',async()=>{els.accessPanel.classList.toggle('hidden');if(!els.accessPanel.classList.contains('hidden'))await loadAccess()});
els.closeAccess.addEventListener('click',()=>els.accessPanel.classList.add('hidden'));
els.addWorkspace.addEventListener('click',addWorkspaceFromUi);els.workspacePath.addEventListener('keydown',event=>{if(event.key==='Enter')addWorkspaceFromUi()});
els.addCommand.addEventListener('click',addCommandFromUi);els.commandCandidate.addEventListener('keydown',event=>{if(event.key==='Enter')addCommandFromUi()});
els.authorizeOperation.addEventListener('click',authorizeOperationFromUi);els.operationArgs.addEventListener('keydown',event=>{if(event.key==='Enter')authorizeOperationFromUi()});
els.refresh.addEventListener('click',async()=>{await refreshProject({reason:'manual',force:true});if(!els.accessPanel.classList.contains('hidden'))await loadAccess()});
els.refreshSemantic.addEventListener('click',refreshSemantics);els.auto.addEventListener('change',schedule);
els.search.addEventListener('input',()=>{invalidate('requirements','detail');renderRequirements();renderDetail()});
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(item=>item.classList.remove('active'));button.classList.add('active');state.filter=button.dataset.filter;invalidate('requirements','detail');renderRequirements();renderDetail()}));
document.querySelectorAll('.arch-mode').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.arch-mode').forEach(item=>item.classList.remove('active'));button.classList.add('active');state.architectureMode=button.dataset.archMode||'overlay';invalidate('architectureGraph');renderArchitectureGraph()}));
document.addEventListener('visibilitychange',async()=>{if(document.hidden){clearTimeout(state.timer);state.timer=null;return}if(els.auto.checked){await refreshProject({reason:'auto'});if(!els.accessPanel.classList.contains('hidden'))await loadAccess();schedule()}});

applyTheme();applyLanguage();refreshProject({workspace:state.current,reason:'initial',force:true}).then(schedule);
